-- Vanlige styrkeøvelser med norske navn (idempotent).
-- Kjør: npx supabase db query --linked -f src/supabase/seed_strength_exercises_no.sql

on conflict (id) do update set
  name = excluded.name,
  category = excluded.category,
  muscle_group = excluded.muscle_group,
  equipment = excluded.equipment,
  level = excluded.level,
  description = excluded.description,
  is_active = true,
  updated_at = now();
